57	function nameMatchesIn(text, name) {
58	  const normalizedName = normalize(name);
59	  const idx = text.indexOf(normalizedName);
60	  if (idx === -1) return false;
61	  const charAfter = text[idx + normalizedName.length];
62	  // Only English identifier-continuation chars count as "not a boundary".
63	  // CJK chars after the name (e.g. "luca-dev 的任务") ARE a boundary, so
64	  // common follow-up particles do not break the match.
65	  const afterOk = charAfter === undefined || !/[a-z0-9_-]/i.test(charAfter);
66	  // Short names (≤2 chars) keep the stricter CJK-also-extends check on both
67	  // sides to avoid false positives like 名"AI"误中"AIxxx".
68	  if (normalizedName.length <= 2) {
69	    const charBefore = idx > 0 ? text[idx - 1] : undefined;
70	    const beforeOk = charBefore === undefined || !/[一-鿿a-z0-9]/i.test(charBefore);
71	    const strictAfterOk = charAfter === undefined || !/[一-鿿a-z0-9]/i.test(charAfter);
72	    return strictAfterOk && beforeOk;
73	  }
74	  return afterOk;
75	}
