286	function classifyRoutingScope(prompt, projects, currentProject) {
287	  const namedProject = projects.find(name => nameMatchesIn(projectIdentityText(prompt), name));
288	  // Some clients surface hook output inside the next visible message. That
289	  // diagnostic text is evidence about the framework, not fresh project intent;
290	  // in particular, the standard "新项目还是继续老项目" wording must not feed
291	  // back into this classifier and manufacture another Project Gate.
292	  const isRouteGuardReport = /UserPromptSubmit\s+hook\s*\(completed\).*hook\s+context:\s*\[route-guard\]/is.test(prompt);
293	  const frameworkSignals = matchingScopeRuleIds(prompt, FRAMEWORK_SCOPE_RULES);
294	  const controlSignals = matchingScopeRuleIds(prompt, FRAMEWORK_CONTROL_RULES);
295	  const scopeResidual = stripScopeRules(
296	    stripScopeRules(prompt, FRAMEWORK_SCOPE_RULES),
297	    FRAMEWORK_CONTROL_RULES,
298	  );
299	  const negatedDownstreamSignals = matchingScopeRuleIds(scopeResidual, NEGATED_DOWNSTREAM_SCOPE_RULES);
300	  const residual = stripScopeRules(scopeResidual, NEGATED_DOWNSTREAM_SCOPE_RULES);
301	  const downstreamSignals = matchingScopeRuleIds(residual, DOWNSTREAM_SCOPE_RULES);
302	
303	  // 具名 identity 仍决定最高优先级的 scope，但不再丢掉同句中的框架/续接信号：目标项目
304	  // 已经激活时 Gate 已满足，后面的 complexity 必须还能看见这些信号。
305	  if (namedProject) {
306	    return { kind: 'named_downstream', namedProject, frameworkSignals, controlSignals, downstreamSignals, negatedDownstreamSignals };
307	  }
308	  if (isRouteGuardReport) {
309	    return { kind: 'pure_framework_meta', frameworkSignals: [...new Set([...frameworkSignals, 'route-guard-report'])], controlSignals, negatedDownstreamSignals };
310	  }
311	  if (!frameworkSignals.length && !controlSignals.length) return { kind: 'ordinary' };
312	
313	  if (downstreamSignals.length) {
314	    const affirmsCurrent = /当前项目|这个项目|本项目/.test(residual) && currentProject;
315	    if (affirmsCurrent) {
316	      return { kind: 'current_downstream', project: currentProject, frameworkSignals, controlSignals, downstreamSignals, negatedDownstreamSignals };
317	    }
318	    return { kind: 'mixed_ambiguous', frameworkSignals, controlSignals, downstreamSignals, negatedDownstreamSignals };
319	  }
320	
321	  return { kind: 'pure_framework_meta', frameworkSignals, controlSignals, negatedDownstreamSignals };
322	}
