357	  // project whose name is a substring (e.g. "项目" ⊂ "新项目"). Strip the
358	  // trigger words before matching existing project names.
359	  const newProjectTriggers = ['新项目', '新需求', '新功能'];
360	  const hasNewProjectSignal = newProjectTriggers.some(t => text.includes(normalize(t)));
361	  const hasNewProjectDeclaration = /新项目|新建(?:一个)?项目|创建(?:一个)?(?:名为.{1,80})?新?项目|new\s+project/i.test(prompt);
362	  const declaredNewProject = explicitNewProjectName(prompt);
363	  let searchText = text;
